import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_record_and_sorts():
    old, b, c, latest = parse_session_log(["a,5,0", "b,2,1", "c,1,1", "a,2,1"])
    assert dedupe_sessions([old, b, c, latest]) == [c, latest, b]


def test_parser_skips_comments_and_blank_lines_and_strips_fields():
    assert parse_session_log(["  # comment", "", " \t", " a , 2 , 0 ", "b,3, "]) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["a,0", "a,0,1,0", "a,two,1"])
def test_parser_errors_include_original_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", "  # comment", "a,1,1", bad])


def test_daily_counts_and_windows():
    events = parse_session_log(["a,0,1", "b,1,1", "c,2,0", "d,4,1", "e,4,1", "f,5,1"])
    counts = daily_conversion_counts(events, 1, 4)
    assert counts == [1, 0, 0, 2]
    assert daily_conversion_counts(events, 2, 1) == []
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 3) == 2
    assert conversions_in_window(counts, 8) == 3


def test_summary_uses_session_weights_calendar_days_and_nonempty_groups():
    groups = {"a": parse_session_log(["x,1,1", "y,3,0"]), "b": parse_session_log(["z,1,1"]), "c": []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"c": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_ties_and_empty_groups():
    groups = {"z": [{"converted": False}], "c": [], "b": [{"converted": True}], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 10) == ["a", "b", "z"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("c", None), ("z", 0.0)]


def test_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 4, -1, 3]) == 2
    assert longest_conversion_streak([]) == 0
